import{_ as s}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/ON.DXVlsWbj.js";import{_ as o}from"./chunks/EN.P9aPnFBv.js";import{_ as a}from"./chunks/OFF.BrU7kQE-.js";import{_ as t}from"./chunks/DIS.DdpTdGGD.js";import{_ as n}from"./chunks/BDM.scaBLLhv.js";import{_ as r,a as l}from"./chunks/M-S-N2.DstR7-iA.js";import{_ as d,o as p,c,a3 as m}from"./chunks/framework.g9mfNVRQ.js";const S=JSON.parse('{"title":"Cloud Upload","description":"","frontmatter":{},"headers":[],"relativePath":"use/cloud.md","filePath":"use/cloud.md"}'),u={name:"use/cloud.md"};function h(g,i,y,b,f,v){return p(),c("div",null,[...i[0]||(i[0]=[m('<div class="admonition xdrip"><p class="admonition-title"><img src="'+s+'" style="zoom:75%;"></p><p> Settings<br>  <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_cloud_upload_grey600_48dp.png" style="width:5%;"> Cloud Upload</p></div><p>Cloud upload allows you to upload your BG to various cloud services or databases.<br> This can be used to share data with non-xDrip devices and for reporting.</p><h3 id="nightscout-sync-rest-api" tabindex="-1">Nightscout Sync (REST-API) <a class="header-anchor" href="#nightscout-sync-rest-api" aria-label="Permalink to &quot;Nightscout Sync (REST-API)&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Nightscout Sync (REST-API)</p><p> The REST API is the standard way to connect to Nightscout</p></div><p><a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a> is the universal method to share your BG numbers, create reports and much more...</p><p>After you have created your Nightscout site, enable Sync to upload data from xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Enabled<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> The REST API is the standard way to connect to Nightscout</p></div><p>If you want to use Nightscout to share your BG, make sure this is enabled if you&#39;re using a cellular phone with a SIM and a data plan. Else it will only upload when connected to a Wi-Fi network, which is fine if you use Nightscout to collect data for reports.</p><div class="admonition xdripitem"><p class="admonition-title">Use mobile data<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Upload even when using mobile data</p></div><p>If you use filters or calibration plugins, you can select this to send to Nightscout the data as displayed by xDrip instead of uncalibrated/unfiltered data.</p><div class="admonition xdripitem"><p class="admonition-title">Send display glucose<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Use noise smoothing and plugins etc. (if enabled) for broadcasted value</p></div><p>The base URL is composed of your API_SECRET (or a token) and the URL of your site.<br> The example provided in the dialog was for an Azure based Nightscout.</p><div class="admonition xdripitem"><p class="admonition-title">Base URL</p><p> Format: <a href="https://password@hostname/api/v1/" target="_blank" rel="noreferrer">https://password@hostname/api/v1/</a></p></div><p>The URL format should be like this:</p><p><strong><code>https://your-API_SECRET@your-site.domain.fqd/api/v1/</code></strong></p><p>You&#39;ll find the API_SECRET in your Nightscout <a href="https://nightscout.github.io/nightscout/setup_variables/#nightscout-configuration" target="_blank" rel="noreferrer">variables</a>.</p><p>Alternatively you can use an admin <a href="https://nightscout.github.io/nightscout/security/#create-authentication-tokens-for-users" target="_blank" rel="noreferrer">token</a> to authenticate, it would then look like this:</p><p><strong><code>https://xdrip-12ab34cd5678ef90@your-site.domain.fqd/api/v1/</code></strong></p><p>Contact the vendor if you use a hosted service.</p><div class="info custom-block"><p class="custom-block-title">Multiple sites</p><p>In case you have more than one Nightscout site, xDrip can upload to multiple <strong>space separated</strong> Nightscout URLs.<br><em><strong>Only BG values will upload to the secondary URL(s), not treatments</strong></em></p></div><p>In case you have several devices uploading to Nightscout (not recommended) you might want to also download treatments from Nightscout to see the information that was uploaded by others.</p><div class="admonition xdripitem"><p class="admonition-title">Download treatments<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Also try to download treatments from Nightscout</p></div><div class="warning custom-block"><p class="custom-block-title">Automatic Calibration</p><p>This is the same <a href="./../calibrate/advancedcal.html#use-treatment-bg-values">Automatic Calibration</a> setup in calibrations. Use with care.</p></div><div class="admonition xdripitem"><p class="admonition-title">Automatic Calibration<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Calibrate using new blood glucose readings if the conditions appear right to do so without asking confirmation (experimental)</p></div><br><div class="admonition xdripitem"><p class="admonition-title">Extra Options</p></div><p>If your Nightscout is available only on a local server (on a private IP), don&#39;t try to upload data to Nightscout when you&#39;re not home. Ignore for cloud based Nightscout.</p><div class="admonition xdripitem"><p class="admonition-title">Skip LAN uploads<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> For local servers with 192.168.x.x addresses, skip uploads when there is no local network connectivity</p></div><p>You can upload your bridge or sensor battery level (if supported).</p><div class="admonition xdripitem"><p class="admonition-title">Upload bridge battery<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Send your bridge battery level to Nightscout. Uncheck if your battery sensor is broken.</p></div><div class="admonition xdripitem"><p class="admonition-title">Upload Dexcom battery<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Send Dexcom transmitter battery statistics to Nightscout. Includes all of the data shown on the Collector Status screen.</p></div><p>You can upload locally entered <a href="./mainUI.html#treatments">treatments</a> to Nightscout <a href="https://nightscout.github.io/nightscout/setup_variables/#careportal-careportal" target="_blank" rel="noreferrer">Care Portal</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Upload treatments<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Send treatment data to Nightscout. Uncheck if your careportal is broken.</p></div><p>You can set up an alert when upload fails, and add more information to the BG data uploaded.</p><div class="admonition xdripitem"><p class="admonition-title">Alert on failures<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Display and sound a notification if Nightscout upload is failing</p></div><div class="admonition xdripitem"><p class="admonition-title">Append source info to device name<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> For Dex, sends collector type (e.g. OB1) and reading backfill status (for native) to Nightscout.</p></div><h5 id="backfill-data-to-nightscout" tabindex="-1">Backfill data to Nightscout <a class="header-anchor" href="#backfill-data-to-nightscout" aria-label="Permalink to &quot;Backfill data to Nightscout&quot;">​</a></h5><p>If you recently created a Nightscout site and want to upload your historical data from xDrip database, you can use back-fill.</p><div class="admonition xdripitem"><p class="admonition-title">Back-fill data</p><p> Send BG readings to backfill</p></div><p>Select the first day of the period you want to upload (until today) and touch <strong>DO IT!</strong><br> Depending on the amount of data and network speed, upload can take a very long time (hours).</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;">Nightscout Backfill</p><p>Choose the date for the oldest record to send to Nightscout. Use with care!</p><div style="background-color:gray;color:white;text-align:center;">  FEBRUARY 12, 2022 11:29PM </div><p><span style="background-color:gray;color:white;text-align:center;">  DO IT! </span> CANCEL</p></div><h3 id="mongodb" tabindex="-1">MongoDB <a class="header-anchor" href="#mongodb" aria-label="Permalink to &quot;MongoDB&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>This method has been deprecated for Nightscout.</p></div><p>You can directly upload BG and device status to a Mongo database.</p><div class="admonition xdripitem"><p class="admonition-title">MongoDB</p><p> Direct database upload, not recommended for Nightscout</p></div><p>MongoDB upload has been deprecated since mLab was acquired by MongoDB and many migrated to Atlas: <strong>you cannot use a DNS seed URI <code>mongodb+srv</code></strong>.<br> Use this feature only if you run your own <a href="https://github.com/mongodb/mongo" target="_blank" rel="noreferrer">Mongo</a> database, default port is 27017.</p><p>The <a href="https://www.mongodb.com/docs/manual/reference/connection-string/#connection-string-uri-format" target="_blank" rel="noreferrer">connection string URI</a> structure is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mongodb://databaseusername:databasepassword@your.mongo.url/databasename</span></span></code></pre></div><p>In order to keep the database compatible with Nightscout, do not change Collection name or Device status collection name from default (if you do change them you&#39;ll also have to modify the corresponding variables in Nightscout <code>MONGODB_COLLECTION</code> and <code>MONGO_DEVICESTATUS_COLLECTION</code>).</p><div class="info custom-block"><p class="custom-block-title">Info</p><p>Uploaded data might not show in the Nightscout web page but only in Nightscout reports.</p></div><h3 id="influxdb" tabindex="-1">InfluxDB <a class="header-anchor" href="#influxdb" aria-label="Permalink to &quot;InfluxDB&quot;">​</a></h3><p>You can also upload to an <a href="https://www.influxdata.com/products/influxdb-overview/" target="_blank" rel="noreferrer">InfluxDB</a> and use Grafana to present your data.</p><div class="admonition xdripitem"><p class="admonition-title">InfluxDB</p><p> If using a private InfluxDB database, this should be enabled</p></div><p>Mind your InfluxDB URI will be expressed like:</p><p><code>https://host_address:port</code> for example for a local server: <code>https://192.168.0.56:8086</code></p><h3 id="dex-share" tabindex="-1">Dex Share <a class="header-anchor" href="#dex-share" aria-label="Permalink to &quot;Dex Share&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Your username cannot be a phone number</p><p>You should create a <a href="https://www.dexcom.com/faqs/how-do-i-create-a-dependent-account" target="_blank" rel="noreferrer">dependent account</a> to have a text-only username.<br> Once you have created the new dependent account, make sure you&#39;re logged in with this account in your Dexcom apps and recreate all followers.</p></div><p>Once you have an active follower, created by the Dexcom apps, you can use xDrip to upload to Dexcom Share.</p><div class="admonition xdripitem"><p class="admonition-title">Dex Share</p><p> Upload data to Dex share servers</p></div><div class="info custom-block"><p class="custom-block-title">Info</p><p>You can upload your BG to Dexcom Share, <strong>not to Dexcom Clarity</strong>.</p></div><div class="admonition xdripitem"><p class="admonition-title">Upload BG values to Dex Share<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Enable this to upload to Dex Share servers</p></div><p>If you use a USA account enable this, <strong>for any other country leave it disabled</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Dex USA based account<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Enabled = Your account and follower apps are from the USA</p></div><p>Enter the credentials you use to log into Clarity.</p><div class="admonition xdripitem"><p class="admonition-title">Dex Account Login</p><p> Your login for Dex share</p></div><div class="admonition xdripitem"><p class="admonition-title">Dex Account Password</p><p> Your password for Dex share</p></div><h3 id="tidepool" tabindex="-1">Tidepool <a class="header-anchor" href="#tidepool" aria-label="Permalink to &quot;Tidepool&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Tidepool</p><p> Upload data to the Tidepool service</p></div><p>If you have a <a href="https://www.tidepool.org/" target="_blank" rel="noreferrer">Tidepool</a> account, you can automatically upload your data and share it with your endocrinologist.<br> If xDrip can display <a href="./display.html#basal-information">basal information from an external status</a>, it will also be uploaded to Tidepool.</p><div class="admonition xdripitem"><p class="admonition-title">Sync to Tidepool<span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>Add your email address and password (those you used to <a href="https://app.tidepool.org/signup/personal" target="_blank" rel="noreferrer">register</a>).</p><div class="admonition xdripitem"><p class="admonition-title">Login User Name</p><p>Your Tidepool login user name, normally your email address</p></div><div class="admonition xdripitem"><p class="admonition-title">Login Password</p><p>Your Tidepool login password</p></div><p>Once done, test the connection.</p><div class="admonition xdripitem"><p class="admonition-title">Test Tidepool Login</p></div><p>Tidepool doesn&#39;t need real time data, select the period data will upload, using the cursor. Default is 15 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Data Age Mins (15)</p></div><p>Do <strong>NOT</strong> use test servers (keep unselected).</p><div class="admonition xdripitem"><p class="admonition-title">Use integration (test) servers<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div><p>You can select to upload under specific conditions to save battery and data costs.</p><div class="admonition xdripitem"><p class="admonition-title">Only when charging<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p>Upload data only when charging</p></div><div class="admonition xdripitem"><p class="admonition-title">Only on Wifi<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p>Upload data only when connected to an unmetered network like Wifi</p></div><p>If you also upload data manually from your pump, you might want to disable xDrip treatments upload to avoid duplicates.</p><div class="admonition xdripitem"><p class="admonition-title">Don&#39;t upload treatments<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p>Upload only CGM data to avoid duplicates with manual pump upload</p></div><h5 id="web-deposit" tabindex="-1">Web Deposit <a class="header-anchor" href="#web-deposit" aria-label="Permalink to &quot;Web Deposit&quot;">​</a></h5><p>Web Deposit is a simple batch upload API currently used for diagnostics. It&#39;s hidden behind Engineering Mode and not intended for regular use.</p><h3 id="nightlite" tabindex="-1">NightLite <a class="header-anchor" href="#nightlite" aria-label="Permalink to &quot;NightLite&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">NightLite</p><p> Lightweight Nightscout compatible service intended for followers</p></div><p>NightLite is a lightweight, Nightscout-compatible follower service, a simpler alternative to running your own Nightscout site if you only need to share your BG with followers.</p><p>See <a href="./nightlite.html">NightLite follower setup</a> for the full install sequence.</p><div class="admonition xdripitem"><p class="admonition-title">Upload to NightLite<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Whether to upload to the remote service</p></div><div class="admonition xdripitem"><p class="admonition-title">NightLite URL</p><p> Typically entered by scanning QR code from dashboard<br>  This contains your security key - do not disclose it</p></div><p>Once enabled, you can show a QR code containing your NightLite connection details for followers to scan.</p><div class="admonition xdripitem"><p class="admonition-title">Show QR Code</p></div><h3 id="nocturne" tabindex="-1">Nocturne <a class="header-anchor" href="#nocturne" aria-label="Permalink to &quot;Nocturne&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Nocturne</p><p> Upload to Nocturne V4 API</p></div><p><a href="https://getnocturne.dev/" target="_blank" rel="noreferrer">Nocturne</a> is the Nightscout Foundation&#39;s modern successor to Nightscout. If you run your own Nocturne instance, xDrip can upload to it directly.</p><div class="admonition xdripitem"><p class="admonition-title">Enable Nocturne upload<span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>Enter the address of your Nocturne instance.</p><div class="admonition xdripitem"><p class="admonition-title">Nocturne instance URL</p><p> Enter the URL of your Nocturne instance (e.g. <a href="https://mynocturne.example.com" target="_blank" rel="noreferrer">https://mynocturne.example.com</a>)</p></div><p>Then authorize xDrip with your instance. No password is stored in xDrip: a code is displayed, which you enter on your Nocturne instance&#39;s approval page in the browser to complete the connection.</p><div class="admonition xdripitem"><p class="admonition-title">Connect to Nocturne</p><p> Authorize xDrip with your Nocturne instance</p></div><h4 id="quick-connect-from-nocturne" tabindex="-1">Quick Connect from Nocturne <a class="header-anchor" href="#quick-connect-from-nocturne" aria-label="Permalink to &quot;Quick Connect from Nocturne&quot;">​</a></h4><p>Instead of typing the instance URL, let Nocturne configure xDrip for you. In your Nocturne instance open Connectors &amp; Apps, then Set Up an Uploader, and select xDrip+ in the CGM Apps list.</p><img src="'+r+'" style="zoom:75%;"><p>The Set up xDrip+ page shows a Quick Connect QR code.</p><img src="'+l+'" style="zoom:60%;"><div class="warning custom-block"><p class="custom-block-title">Scan this QR code with your phone camera app, not with xDrip</p><p>The Quick Connect QR code is a link that opens xDrip on your phone directly on the Nocturne connector configuration. Scanning it with the xDrip <a href="./copysettings.html#auto-configure">Auto configure</a> settings importer will not work.</p></div><p>xDrip then displays an authorization code. Enter it in the Enter Authorization Code field of the same Nocturne page and touch Continue to complete the connection.</p><h4 id="alternate-method-settings-qr-code" tabindex="-1">Alternate method: settings QR code <a class="header-anchor" href="#alternate-method-settings-qr-code" aria-label="Permalink to &quot;Alternate method: settings QR code&quot;">​</a></h4><p>If you prefer to prepare the Nocturne settings yourself, use the configurator below. Enter your instance URL, choose what to upload, then scan the generated QR code from inside xDrip with <a href="./copysettings.html#auto-configure">Auto configure</a> (Camera, or QR code from file with the downloaded PNG). xDrip lists the settings and asks for confirmation before applying them.</p><div class="info custom-block"><p class="custom-block-title">Unlike the Quick Connect QR code above, this one must be scanned with xDrip, not with the camera app.</p></div><p>Once the settings are imported, open Settings, Cloud Upload, Nocturne, touch Connect to Nocturne and enter the authorization code shown by xDrip on your Nocturne instance. Authorization tokens are never part of the QR code.</p><iframe src="./nocturne-qr.html" title="xDrip+ Nocturne QR configurator" style="width:100%;height:800px;border:1px solid #d9dee5;border-radius:8px;background:#f6f7f9;" loading="lazy"></iframe><p>You can also <a href="./nocturne-qr.html" target="_blank">open the configurator in a separate page</a>.</p><p>Select which data to upload. Glucose readings are enabled by default; everything else is optional.</p><div class="admonition xdripitem"><p class="admonition-title">Upload SGV<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Upload CGM sensor glucose readings</p></div><div class="admonition xdripitem"><p class="admonition-title">Upload treatments<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Upload boluses, carbs, notes and device events</p></div><div class="admonition xdripitem"><p class="admonition-title">Upload calibrations<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Upload sensor calibrations</p></div><div class="admonition xdripitem"><p class="admonition-title">Upload blood tests<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Upload fingerstick meter readings</p></div><div class="admonition xdripitem"><p class="admonition-title">Upload heart rate<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Upload heart rate data</p></div><div class="admonition xdripitem"><p class="admonition-title">Upload step count<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Upload step count data</p></div><div class="admonition xdripitem"><p class="admonition-title">Upload device status<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Upload phone battery level and charging state</p></div><div class="admonition xdripitem"><p class="admonition-title">Upload motion tracking<span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Upload recognized activity classifications</p></div><div class="admonition xdripitem"><p class="admonition-title">Use mobile data<span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Allow uploads over mobile data</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',127)])])}const T=d(u,[["render",h]]);export{S as __pageData,T as default};
